```sql
SELECT continents.ContId, continents.Continent, COUNT(countries.CountryId) FROM continents LEFT JOIN countries ON continents.ContId = countries.Continent GROUP BY continents.ContId, continents.Continent;
```

```sql
SELECT T2.Model FROM car_names AS T1 JOIN model_list AS T2 ON T1.Model = T2.Model JOIN cars_data AS T3 ON T1.MakeId = T3.Id ORDER BY T3.Horsepower LIMIT 1;
```

```sql
SELECT T1.Model FROM model_list AS T1 JOIN car_names AS T2 ON T1.Model = T2.Model JOIN cars_data AS T3 ON T2.MakeId = T3.Id ORDER BY T3.MPG DESC LIMIT 1;
```

```sql
SELECT T.Name FROM teacher AS T JOIN course_arrange AS CA ON T.Teacher_ID = CA.Teacher_ID GROUP BY T.Teacher_ID, T.Name HAVING COUNT(DISTINCT CA.Course_ID) >= 2;
```

```sql
SELECT COUNT(*) FROM museum WHERE Open_Year > 2013 OR Open_Year < 2008;
```

```sql
SELECT winner_name, loser_name FROM matches WHERE minutes = (SELECT MAX(minutes) FROM matches);
```

```sql
SELECT winner_name, winner_rank FROM matches ORDER BY winner_age ASC LIMIT 3;
```

```sql
SELECT name, tonnage FROM ship ORDER BY name DESC;
```

```sql
SELECT note FROM death WHERE note LIKE '%East%';
```

```sql
SELECT transcript_date, other_details FROM Transcripts ORDER BY transcript_date ASC LIMIT 1;
```

```sql
SELECT Episode FROM TV_series ORDER BY Rating;
```

```sql
SELECT AVG(LifeExpectancy) FROM country WHERE Continent = 'Africa' AND GovernmentForm = 'Republic';
```

```sql
SELECT Code FROM country WHERE Code NOT IN (SELECT CountryCode FROM countrylanguage WHERE Language = 'English');
```

```sql
SELECT Year_of_Founded FROM orchestra WHERE Orchestra_ID IN (SELECT Orchestra_ID FROM performance GROUP BY Orchestra_ID HAVING COUNT(*) > 1);
```

```sql
SELECT COUNT(*) FROM Highschooler WHERE grade IN (9, 10);
```

```sql
SELECT COUNT(*) FROM Likes JOIN Highschooler ON Likes.liked_id = Highschooler.ID WHERE Highschooler.name = 'Kyle';
```

